#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

char* nextClosestTime(char* time) {
    int h = (time[0]-'0')*10 + (time[1]-'0');
    int m = (time[3]-'0')*10 + (time[4]-'0');
    int cur = h*60 + m;
    bool allowed[10] = {false};
    for (int i = 0; i < 5; ++i) {
        if (time[i] >= '0' && time[i] <= '9') allowed[time[i]-'0'] = true;
    }

    static char result[6];
    for (int step = 1; step <= 1440; ++step) {
        int value = (cur + step) % 1440;
        int hh = value / 60;
        int mm = value % 60;
        result[0] = (char)('0' + hh / 10);
        result[1] = (char)('0' + hh % 10);
        result[2] = ':';
        result[3] = (char)('0' + mm / 10);
        result[4] = (char)('0' + mm % 10);
        result[5] = '\0';

        bool ok = true;
        for (int i = 0; i < 5; ++i) {
            if (result[i] != ':' && !allowed[result[i]-'0']) {
                ok = false;
                break;
            }
        }
        if (ok) return result;
    }
    strcpy(result, time);
    return result;
}

