class Solution {
public:
    string nextClosestTime(string time) {
        int h = stoi(time.substr(0, 2));
        int m = stoi(time.substr(3, 2));
        int cur = h * 60 + m;
        bool allowed[10] = {};
        for (char c : time) {
            if (c >= '0' && c <= '9') allowed[c - '0'] = true;
        }
        for (int step = 1; step <= 1440; ++step) {
            int value = (cur + step) % 1440;
            int hh = value / 60;
            int mm = value % 60;
            char buf[6];
            snprintf(buf, sizeof(buf), "%02d:%02d", hh, mm);
            bool ok = true;
            for (int i = 0; i < 5; ++i) {
                if (buf[i] != ':' && !allowed[buf[i] - '0']) {
                    ok = false;
                    break;
                }
            }
            if (ok) return string(buf);
        }
        return time;
    }
};

