const readline = require('readline');

function nextClosestTime(time) {
    const h = Number(time.slice(0, 2));
    const m = Number(time.slice(3, 5));
    const cur = h * 60 + m;
    const allowed = new Set(time.replace(':', '').split(''));
    for (let step = 1; step <= 1440; step++) {
        const value = (cur + step) % 1440;
        const hh = Math.floor(value / 60);
        const mm = value % 60;
        const candidate = String(hh).padStart(2, '0') + ':' + String(mm).padStart(2, '0');
        let ok = true;
        for (const ch of candidate) {
            if (ch !== ':' && !allowed.has(ch)) { ok = false; break; }
        }
        if (ok) return candidate;
    }
    return time;
}

